//! Original base/context/entity mutation methods via archive access shims.
use std::{collections::BTreeMap,io::{self,BufRead},sync::{Arc,Mutex,atomic::{AtomicU64,Ordering}},future::Future,task::{Context,Poll,Wake,Waker},panic::{catch_unwind,AssertUnwindSafe}};
use serde_json::{json,Value as J};
use teaql_core::*;use teaql_data_service::*;
use teaql_runtime::{UserContext,RuntimeModule,RuntimeError,RequestPolicy,EntityDataServiceBehavior,RawAuditEventSink,RawAuditEvent,InternalIdGenerator,AggregationCacheBackend,EntityValues,ObjectLocation,CheckResults,Checker,__CppMutation,__cpp_mutation};
mod fixture_value;
#[derive(Default)]struct State{notes:Mutex<Vec<String>>,requests:Mutex<Vec<J>>,events:Mutex<Vec<J>>}
impl State{fn note(&self,v:&str){self.notes.lock().unwrap().push(v.into())}}
fn record(j:&J)->BTreeMap<String,Value>{j.as_object().unwrap().iter().map(|(k,v)|(k.clone(),fixture_value::value(v))).collect()}
fn record_out(v:&BTreeMap<String,Value>)->J{json!(v.iter().map(|(k,v)|(k.clone(),format!("{v:?}"))).collect::<BTreeMap<_,_>>())}
fn trace(j:&J)->Vec<TraceNode>{j.as_array().unwrap().iter().map(|n|TraceNode{kind:[TraceKind::AuditReason,TraceKind::Entity,TraceKind::Comment][n["kind"].as_u64().unwrap()as usize],entity_type:n["entity"].as_str().unwrap().into(),entity_id:None,comment:n["comment"].as_str().unwrap().into()}).collect()}
fn trace_out(v:&[TraceNode])->J{json!(v.iter().map(|n|json!({"kind":n.kind as u8,"entity":n.entity_type,"comment":n.comment})).collect::<Vec<_>>())}
fn request_out(r:&MutationRequest)->J{match r{
 MutationRequest::Insert(c)=>json!({"kind":"insert","entity":c.entity,"values":record_out(&c.values),"trace":trace_out(&c.trace_chain)}),
 MutationRequest::Update(c)=>json!({"kind":"update","entity":c.entity,"id":format!("{:?}",c.id),"version":c.expected_version,"values":record_out(&c.values),"old":c.old_values.as_ref().map(|s|record_out(s)),"trace":trace_out(&c.trace_chain)}),
 MutationRequest::Delete(c)=>json!({"kind":"delete","entity":c.entity,"id":format!("{:?}",c.id),"version":c.expected_version,"trace":trace_out(&c.trace_chain)}),
 MutationRequest::Recover(c)=>json!({"kind":"recover","entity":c.entity,"id":format!("{:?}",c.id),"version":c.expected_version,"trace":trace_out(&c.trace_chain)}),_=>panic!("unexpected batch request")}}
struct Mock{state:Arc<State>,counts:Vec<u64>,failure:i64}
impl DataServiceExecutor for Mock{type Error=io::Error;fn capabilities(&self)->DataServiceCapabilities{DataServiceCapabilities::default()}}
impl QueryExecutor for Mock{async fn query(&self,_:QueryRequest)->Result<QueryResult,Self::Error>{panic!("audit mutation must not reread")}}
impl Mock{async fn execute(&self,r:MutationRequest,observer:Option<ExecutionObserver<'_>>)->Result<MutationResult,io::Error>{let index=self.state.requests.lock().unwrap().len();self.state.requests.lock().unwrap().push(request_out(&r));self.state.note("provider");let count=self.counts.get(index).copied().unwrap_or(1);let mut metadata=ExecutionMetadata::unrecorded_query(0);metadata.operation=DataServiceOperation::Update;metadata.result_count=None;metadata.backend="fixture".into();metadata.affected_rows=Some(count);metadata.parameterized_query=Some("UPDATE fixture SET value = ?".into());if let Some(observer)=observer{self.state.note("observer");observer(metadata.clone())}if self.failure==index as i64{return Err(io::Error::other("provider failed"))}Ok(MutationResult{affected_rows:count,generated_values:GeneratedValues::new(),persisted_snapshot:None,metadata})}}
impl MutationExecutor for Mock{
 async fn mutate(&self,r:MutationRequest)->Result<MutationResult,Self::Error>{self.execute(r,None).await}
 async fn mutate_observed<'a>(&'a self,r:MutationRequest,o:Option<ExecutionObserver<'a>>)->Result<MutationResult,Self::Error>{self.execute(r,o).await}
}
struct Sink{state:Arc<State>,failure:i64}
impl RawAuditEventSink for Sink{fn on_event(&self,_:&UserContext,e:&RawAuditEvent)->Result<(),RuntimeError>{self.state.note("event");let index=self.state.events.lock().unwrap().len();self.state.events.lock().unwrap().push(json!({"kind":format!("{:?}",e.kind),"entity":e.entity,"values":record_out(&e.values),"old":e.old_values.as_ref().map(record_out),"new":e.new_values.as_ref().map(record_out),"fields":e.updated_fields,"trace":trace_out(&e.trace_chain)}));if index as i64==self.failure{Err(RuntimeError::Event("event failed".into()))}else{Ok(())}}}
struct Cache(Arc<State>);impl AggregationCacheBackend for Cache{fn namespace(&self)->&str{"fixture"}fn get(&self,_:&str,_:u64)->Option<Vec<CompactRow>>{None}fn put(&self,_:String,_:Vec<CompactRow>){}fn invalidate_namespace(&self,n:&str){self.0.note(n)}}
struct Id{next:Arc<AtomicU64>,state:Arc<State>}impl InternalIdGenerator for Id{fn generate_id(&self,_:&str)->Result<u64,RuntimeError>{self.state.note("id");Ok(self.next.fetch_add(1,Ordering::Relaxed))}}
struct Hook{state:Arc<State>,mode:String}impl Hook{fn call(&self,values:Option<&mut MutationValues>)->Result<(),RuntimeError>{self.state.note("hook");if self.mode=="error"{return Err(RuntimeError::Behavior("hook failed".into()))}if self.mode=="set"{if let Some(v)=values{v.insert("name".into(),"hook".into());}}Ok(())}}
impl EntityDataServiceBehavior for Hook{fn before_insert(&self,_:&UserContext,c:&mut InsertCommand)->Result<(),RuntimeError>{self.call(Some(&mut c.values))}fn before_update(&self,_:&UserContext,c:&mut UpdateCommand)->Result<(),RuntimeError>{self.call(Some(&mut c.values))}fn before_delete(&self,_:&UserContext,_:&mut DeleteCommand)->Result<(),RuntimeError>{self.call(None)}fn before_recover(&self,_:&UserContext,_:&mut RecoverCommand)->Result<(),RuntimeError>{self.call(None)}}
struct Policy(Hook);impl RequestPolicy for Policy{fn enforce_insert(&self,_:&UserContext,c:&mut InsertCommand)->Result<(),RuntimeError>{self.call(Some(&mut c.values))}fn enforce_update(&self,_:&UserContext,c:&mut UpdateCommand)->Result<(),RuntimeError>{self.call(Some(&mut c.values))}fn enforce_delete(&self,_:&UserContext,_:&mut DeleteCommand)->Result<(),RuntimeError>{self.call(None)}fn enforce_recover(&self,_:&UserContext,_:&mut RecoverCommand)->Result<(),RuntimeError>{self.call(None)}}
impl Policy{fn call(&self,values:Option<&mut MutationValues>)->Result<(),RuntimeError>{self.0.state.note("policy");if self.0.mode=="error"{return Err(RuntimeError::Policy("policy failed".into()))}if self.0.mode=="set"{if let Some(v)=values{v.insert("name".into(),"policy".into());}}Ok(())}}
struct Fix(Arc<State>);impl Checker for Fix{fn entity(&self)->&str{"Order"}fn check_and_fix(&self,_:&UserContext,v:&mut EntityValues,_:&ObjectLocation,_:&mut CheckResults){self.0.note("fix");v.insert("name".into(),"fixed".into());}}
fn command(j:&J)->__CppMutation{let name=j["entity"].as_str().unwrap();let mut insert=InsertCommand::new(name);insert.values=record(&j["values"]).into();insert.trace_chain=trace(&j["trace"]);let mut update=UpdateCommand::new(name,fixture_value::value(&j["id"]));update.values=record(&j["values"]).into();update.trace_chain=trace(&j["trace"]);update.expected_version=j["version"].as_i64();update.old_values=j["old"].as_object().map(|_|record(&j["old"]).into());let mut delete=DeleteCommand::new(name,fixture_value::value(&j["id"]));delete.expected_version=j["version"].as_i64();delete.trace_chain=trace(&j["trace"]);let mut recover=RecoverCommand::new(name,fixture_value::value(&j["id"]),j["version"].as_i64().unwrap_or(1));recover.trace_chain=trace(&j["trace"]);
match j["entry"].as_str().unwrap(){"insert"=>__CppMutation::Insert(insert),"update"=>__CppMutation::Update(update),"delete"=>__CppMutation::Delete(delete),"recover"=>__CppMutation::Recover(recover),"inserts"=>__CppMutation::Inserts(vec![insert.clone(),insert]),"updates"=>__CppMutation::Updates(vec![update.clone(),update]),"deletes"=>__CppMutation::Deletes(vec![delete.clone(),delete]),"recovers"=>__CppMutation::Recovers(vec![recover.clone(),recover]),"batch_insert"=>{let mut b=BatchInsertCommand::new(name);b.batch_values=j["batch"].as_array().unwrap().iter().map(|v|record(v).into()).collect();b.trace_chains=j["traces"].as_array().unwrap().iter().map(trace).collect();__CppMutation::BatchInsert(b)},"batch_update"=>{let mut b=BatchUpdateCommand::new(name,j["fields"].as_array().unwrap().iter().map(|s|s.as_str().unwrap().into()).collect());b.batch_values=j["batch"].as_array().unwrap().iter().map(|v|record(v).into()).collect();b.batch_ids=j["ids"].as_array().unwrap().iter().map(fixture_value::value).collect();b.batch_expected_versions=j["versions"].as_array().unwrap().iter().map(|v|v.as_i64()).collect();b.batch_old_values=j["olds"].as_array().unwrap().iter().map(|v|v.as_object().map(|_|record(v).into())).collect();b.trace_chains=j["traces"].as_array().unwrap().iter().map(trace).collect();__CppMutation::BatchUpdate(b)},_=>panic!("unknown entry")}}
struct NoWake;impl Wake for NoWake{fn wake(self:Arc<Self>){}}fn wait<F:Future>(f:F)->F::Output{let mut f=std::pin::pin!(f);let w=Waker::from(Arc::new(NoWake));let mut cx=Context::from_waker(&w);loop{if let Poll::Ready(v)=f.as_mut().poll(&mut cx){return v}}}
fn evaluate(j:J)->J{let state=Arc::new(State::default());let mut module=RuntimeModule::new().event_sink(Sink{state:state.clone(),failure:j["event_fail"].as_i64().unwrap()});if j["metadata"]==true{let mut d=EntityDescriptor::new("Order").property(PropertyDescriptor::new("id",DataType::U64).id()).property(PropertyDescriptor::new("version",DataType::I64).version());let p=PropertyDescriptor::new("name",DataType::Text);d=d.property(if j["required"]==true{p.not_null()}else{p});module=module.descriptor(d);}if j["hook"]!="none"{module=module.behavior("Order",Hook{state:state.clone(),mode:j["hook"].as_str().unwrap().into()})}if j["fix"]==true{module=module.checker(Fix(state.clone()))}
 let mut context=module.into_context();context.set_user_identifier("fixture");context.disable_sql_log();if j["log"]==true{context.enable_mutation_sql_log();}if j["policy"]!="none"{context.set_request_policy(Policy(Hook{state:state.clone(),mode:j["policy"].as_str().unwrap().into()}))}if j["cache"]==true{let cache:Arc<dyn AggregationCacheBackend>=Arc::new(Cache(state.clone()));context.insert_resource(cache);}let next=Arc::new(AtomicU64::new(100));context.set_internal_id_generator(Id{next:next.clone(),state:state.clone()});let mock=Mock{state:state.clone(),counts:j["counts"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()).collect(),failure:j["fail"].as_i64().unwrap()};let result=catch_unwind(AssertUnwindSafe(||wait(__cpp_mutation(&context,&mock,j["layer"].as_str().unwrap(),command(&j),trace(&j["lineage"])))));let outcome=match result{Ok(Ok(n))=>json!({"rows":n}),Ok(Err(e))=>json!({"error":e.to_string()}),Err(_)=>json!({"panic":true})};let output=json!({"outcome":outcome,"notes":*state.notes.lock().unwrap(),"requests":*state.requests.lock().unwrap(),"events":*state.events.lock().unwrap(),"logs":context.sql_logs().len(),"next_id":next.load(Ordering::Relaxed)});output}
fn main(){std::panic::set_hook(Box::new(|_|{}));unsafe{std::env::set_var("TEAQL_LOG_ENDPOINT","off");}for line in io::stdin().lock().lines(){println!("{}",evaluate(serde_json::from_str(&line.unwrap()).unwrap()));}}
